output.arguments:
{"command":"cat > /workspace/src/config.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

type Kind int

const (
	KindInfo Kind = iota
	KindBool
	KindInt
	KindEnum
	KindString
	KindList
	KindObsolete
	KindDisabled
)

type ConfigItem struct {
	Kind     Kind
	Name     string
	Doc      []string
	DefStr   string
	DefList  []string
	Min, Max int
	EnumVals []string
	Depends  string
	OrgKind  Kind // for obsolete/disabled options

	// runtime values
	Str         string   // raw value string
	List        []string // list values
	IntVal      int
	BoolVal     bool
	UserComment string
	Present     bool
}

var obsoleteOptions = []struct {
	name string
	kind Kind
}{
	{"USE_WINDOWS_ENCODING", KindBool}, {"DETAILS_AT_TOP", KindBool}, {"QTHELP_FILE", KindString},
	{"QTHELP_CONFIG", KindString}, {"DOXYGEN2QTHELP_LOC", KindString}, {"MAX_DOT_GRAPH_WIDTH", KindInt},
	{"MAX_DOT_GRAPH_HEIGHT", KindInt}, {"CGI_NAME", KindString}, {"CGI_URL", KindString},
	{"DOC_URL", KindString}, {"DOC_ABSPATH", KindString}, {"BIN_ABSPATH", KindString},
	{"EXT_DOC_PATHS", KindList}, {"USE_INLINE_TREES", KindBool}, {"SHOW_DIRECTORIES", KindBool},
	{"HTML_ALIGN_MEMBERS", KindBool}, {"SYMBOL_CACHE_SIZE", KindInt}, {"XML_SCHEMA", KindString},
	{"XML_DTD", KindString}, {"PERL_PATH", KindString}, {"MSCGEN_PATH", KindString},
	{"CLASS_DIAGRAMS", KindBool}, {"DOT_FONTNAME", KindString}, {"DOT_FONTSIZE", KindInt},
	{"DOT_TRANSPARENT", KindBool}, {"FORMULA_TRANSPARENT", KindBool}, {"LATEX_SOURCE_CODE", KindBool},
	{"RTF_SOURCE_CODE", KindBool}, {"DOCBOOK_PROGRAMLISTING", KindBool}, {"COLS_IN_ALPHA_INDEX", KindInt},
	{"OUTPUT_TEXT_DIRECTION", KindEnum}, {"TCL_SUBST", KindList}, {"HTML_TIMESTAMP", KindBool},
	{"LATEX_TIMESTAMP", KindBool},
}

var disabledOptions = []struct {
	name string
	kind Kind
}{
	{"CLANG_ASSISTED_PARSING", KindBool}, {"CLANG_ADD_INC_PATHS", KindBool},
	{"CLANG_OPTIONS", KindList}, {"CLANG_DATABASE_PATH", KindString},
}

type Config struct {
	items   []*ConfigItem
	byName  map[string]*ConfigItem
	extra   []*ConfigItem // obsolete & disabled
	pendingUserComment string
}

var cfg *Config

func newConfig() *Config {
	c := &Config{byName: map[string]*ConfigItem{}}
	for _, it := range configItems {
		n := *it
		ni := &n
		c.items = append(c.items, ni)
		if ni.Kind != KindInfo {
			c.byName[ni.Name] = ni
		}
	}
	for _, o := range obsoleteOptions {
		ni := &ConfigItem{Kind: KindObsolete, Name: o.name, OrgKind: o.kind}
		c.extra = append(c.extra, ni)
		c.byName[o.name] = ni
	}
	for _, o := range disabledOptions {
		ni := &ConfigItem{Kind: KindDisabled, Name: o.name, OrgKind: o.kind}
		c.extra = append(c.extra, ni)
		c.byName[o.name] = ni
	}
	c.init()
	return c
}

// init sets all values to their defaults
func (c *Config) init() {
	for _, it := range c.items {
		switch it.Kind {
		case KindList:
			it.List = append([]string(nil), it.DefList...)
		case KindInfo:
		default:
			it.Str = it.DefStr
		}
		it.UserComment = ""
	}
}

func (c *Config) get(name string) *ConfigItem { return c.byName[name] }

func cfgStr(name string) string {
	it := cfg.byName[name]
	if it == nil {
		panic("unknown option " + name)
	}
	return it.Str
}

func cfgBool(name string) bool {
	it := cfg.byName[name]
	if it == nil {
		panic("unknown option " + name)
	}
	return it.BoolVal
}

func cfgInt(name string) int {
	it := cfg.byName[name]
	if it == nil {
		panic("unknown option " + name)
	}
	return it.IntVal
}

func cfgList(name string) []string {
	it := cfg.byName[name]
	if it == nil {
		panic("unknown option " + name)
	}
	return it.List
}

func cfgEnum(name string) string { return cfgStr(name) }

func cfgSetStr(name, v string) { cfg.byName[name].Str = v }
func cfgSetBool(name string, v bool) {
	it := cfg.byName[name]
	it.BoolVal = v
	if v {
		it.Str = "YES"
	} else {
		it.Str = "NO"
	}
}

// ---------------------------------------------------------------------------
// Parsing

func configWarn(format string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, "warning: "+format, args...)
}

func configErr(format string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, "error: "+format, args...)
}

type cfgParser struct {
	c            *Config
	update       bool
	lineNr       int
	fileName     string
	includePaths []string
	includeDepth int
}

func isTagStart(b byte) bool {
	return b == '_' || (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z')
}
func isTagChar(b byte) bool { return isTagStart(b) || (b >= '0' && b <= '9') }

func isSpaceByte(b byte) bool {
	return b == ' ' || b == '\t' || b == '\n' || b == '\r' || b == '\f' || b == '\v'
}

// parse parses config content. Returns false on fatal error.
func (p *cfgParser) parse(data []byte) bool {
	s := data
	n := len(s)
	i := 0
	for i < n {
		ch := s[i]
		// <*>\r is ignored
		if ch == '\r' {
			i++
			continue
		}
		if ch == '#' {
			// comment
			if i+1 < n && s[i+1] == '#' {
				j := i
				for j < n && s[j] != '\n' {
					j++
				}
				if j < n { // "##".*"\n"
					p.c.pendingUserComment += string(s[i:j+1])
					p.lineNr++
					i = j + 1
					continue
				}
				// no newline: falls through to single-char handling
				i = n
				continue
			}
			j := i
			for j < n && s[j] != '\n' {
				j++
			}
			if j < n {
				p.lineNr++
				i = j + 1
			} else {
				i = n
			}
			continue
		}
		if isTagStart(ch) {
			j := i
			for j < n && isTagChar(s[j]) {
				j++
			}
			k := j
			for k < n && (s[k] == ' ' || s[k] == '\t') {
				k++
			}
			if k < n && s[k] == '=' {
				name := string(s[i:j])
				i = p.handleAssign(s, k+1, name, false)
				continue
			}
			if k+1 < n && s[k] == '+' && s[k+1] == '=' {
				name := string(s[i:j])
				i = p.handleAssign(s, k+2, name, true)
				continue
			}
			// unknown tag: [a-z_A-Z0-9]+
			configWarn("ignoring unknown tag '%s' at line %d, file %s\n", string(s[i:j]), p.lineNr, p.fileName)
			i = j
			continue
		}
		if ch >= '0' && ch <= '9' {
			j := i
			for j < n && isTagChar(s[j]) {
				j++
			}
			configWarn("ignoring unknown tag '%s' at line %d, file %s\n", string(s[i:j]), p.lineNr, p.fileName)
			i = j
			continue
		}
		if ch == '@' {
			rest := s[i:]
			if hasPrefixAssign(rest, "@INCLUDE_PATH") {
				k := i + len("@INCLUDE_PATH")
				for s[k] != '=' {
					k++
				}
				var raw string
				i, raw = p.readRaw(s, k+1)
				lst := p.processList(raw, "@INCLUDE_PATH")
				p.includePaths = lst
				continue
			}
			if hasPrefixAssign(rest, "@INCLUDE") {
				k := i + len("@INCLUDE")
				for s[k] != '=' {
					k++
				}
				k++
				// skip spaces (fall-through rule)
				for k < n && (s[k] == ' ' || s[k] == '\t' || s[k] == '\r') {
					k++
				}
				if k < n && s[k] == '"' {
					e := k + 1
					for e < n && s[e] != '"' && s[e] != '\n' {
						e++
					}
					if e < n && s[e] == '"' && e > k+1 {
						name := string(s[k : e+1])
						if !p.readIncludeFile(name) {
							return false
						}
						i = e + 1
						continue
					}
				}
				e := k
				for e < n && !(s[e] == ' ' || s[e] == '"' || s[e] == '\t' || s[e] == '\r' || s[e] == '\n') {
					e++
				}
				if e > k {
					name := string(s[k:e])
					if !p.readIncludeFile(name) {
						return false
					}
					i = e
					continue
				}
				i = k
				continue
			}
		}
		if ch == '\\' {
			// <*>\\[ \r\t]*\n
			k := i + 1
			for k < n && (s[k] == ' ' || s[k] == '\r' || s[k] == '\t') {
				k++
			}
			if k < n && s[k] == '\n' {
				p.lineNr++
				i = k + 1
				continue
			}
		}
		if ch == ' ' || ch == '\t' {
			i++
			continue
		}
		if ch == '\n' {
			p.lineNr++
			i++
			continue
		}
		// unknown character (print a full utf-8 char byte by byte like flex does with '.')
		configWarn("ignoring unknown character '%c' at line %d, file %s\n", rune(ch), p.lineNr, p.fileName)
		if ch >= 0x80 {
			// flex '.' matches a single byte; print raw byte
		}
		i++
	}
	return true
}

func hasPrefixAssign(s []byte, kw string) bool {
	if len(s) < len(kw) || string(s[:len(kw)]) != kw {
		return false
	}
	k := len(kw)
	for k < len(s) && (s[k] == ' ' || s[k] == '\t') {
		k++
	}
	return k < len(s) && s[k] == '='
}

// readRaw reads the raw value of an option from position i until an unescaped newline.
// Returns the new position and the raw string. Handles line continuations.
// If EOF is reached before newline, returns complete=false via p.eofHit.
func (p *cfgParser) readRaw(s []byte, i int) (int, string) {
	var b strings.Builder
	n := len(s)
	p.eofHit = false
	for i < n {
		ch := s[i]
		if ch == '\r' {
			i++
			continue
		}
		if ch == '\n' {
			p.lineNr++
			return i + 1, b.String()
		}
		if ch == '\\' {
			k := i + 1
			for k < n && (s[k] == ' ' || s[k] == '\r' || s[k] == '\t') {
				k++
			}
			if k < n && s[k] == '\n' {
				p.lineNr++
				b.WriteByte(' ')
				i = k + 1
				continue
			}
			b.WriteByte('\\')
			i++
			continue
		}
		b.WriteByte(ch)
		i++
	}
	p.eofHit = true
	return i, b.String()
}

func (p *cfgParser) handleAssign(s []byte, i int, name string, appendOp bool) int {
	opt := p.c.get(name)
	if opt == nil {
		configWarn("ignoring unsupported tag '%s' at line %d, file %s\n", name, p.lineNr, p.fileName)
		ni, _ := p.readRaw(s, i)
		return ni
	}
	if appendOp {
		switch opt.Kind {
		case KindList:
			opt.UserComment += p.takeUserComment()
			ni, raw := p.readRaw(s, i)
			if !p.eofHit {
				opt.List = append(opt.List, p.processList(raw, name)...)
			}
			return ni
		case KindEnum, KindString, KindInt, KindBool:
			configWarn("operator += not supported for '%s'. Ignoring line at line %d, file %s\n", name+" +=", p.lineNr, p.fileName)
			ni, _ := p.readRaw(s, i)
			return ni
		case KindObsolete:
			configWarn("Tag '%s' at line %d of file %s has become obsolete.\nTo avoid this warning please update your configuration file using \"doxygen -u\"\n", name, p.lineNr, p.fileName)
			ni, _ := p.readRaw(s, i)
			return ni
		case KindDisabled:
			configWarn("Tag '%s' at line %d of file %s belongs to an option that was not enabled at compile time.\nTo avoid this warning please remove this line from your configuration file, upgrade it using \"doxygen -u\", or recompile doxygen with this feature enabled.\n", name, p.lineNr, p.fileName)
			ni, _ := p.readRaw(s, i)
			return ni
		}
		ni, _ := p.readRaw(s, i)
		return ni
	}
	switch opt.Kind {
	case KindList:
		opt.UserComment = p.takeUserComment()
		opt.List = nil
		ni, raw := p.readRaw(s, i)
		if !p.eofHit {
			opt.List = p.processList(raw, name)
		}
		return ni
	case KindEnum, KindString, KindInt, KindBool:
		opt.UserComment = p.takeUserComment()
		ni, raw := p.readRaw(s, i)
		if !p.eofHit {
			opt.Str = p.processString(raw, name)
		} else {
			opt.Str = raw
		}
		if name == "DOXYFILE_ENCODING" {
			// encoding handling is not needed (UTF-8 assumed)
		}
		return ni
	case KindObsolete:
		opt.UserComment = p.takeUserComment()
		if p.update {
			configWarn("Tag '%s' at line %d of file '%s' has become obsolete.\n         This tag has been removed.\n", name, p.lineNr, p.fileName)
		} else {
			configWarn("Tag '%s' at line %d of file '%s' has become obsolete.\n         To avoid this warning please remove this line from your configuration file or upgrade it using \"doxygen -u\"\n", name, p.lineNr, p.fileName)
		}
		opt.Present = true
		ni, raw := p.readRaw(s, i)
		if opt.OrgKind == KindList {
			opt.List = nil
			if !p.eofHit {
				opt.List = p.processList(raw, name)
			}
		} else {
			if !p.eofHit {
				opt.Str = p.processString(raw, name)
			} else {
				opt.Str = raw
			}
		}
		return ni
	case KindDisabled:
		opt.UserComment = p.takeUserComment()
		if p.update {
			configWarn("Tag '%s' at line %d of file '%s' belongs to an option that was not enabled at compile time.\n         This tag has been removed.\n", name, p.lineNr, p.fileName)
		} else {
			configWarn("Tag '%s' at line %d of file '%s' belongs to an option that was not enabled at compile time.\n         To avoid this warning please remove this line from your configuration file or upgrade it using \"doxygen -u\", or recompile doxygen with this feature enabled.\n", name, p.lineNr, p.fileName)
		}
		ni, _ := p.readRaw(s, i)
		return ni
	}
	ni, _ := p.readRaw(s, i)
	return ni
}

func (p *cfgParser) takeUserComment() string {
	r := p.c.pendingUserComment
	p.c.pendingUserComment = ""
	return r
}

// stripComment removes a trailing comment from a value.
func (p *cfgParser) stripComment(s string) string {
	insideQuote := false
	l := len(s)
	for i := 0; i < l; i++ {
		c := s[i]
		if c == '\\' {
			i++
		} else if c == '"' {
			insideQuote = !insideQuote
		} else if !insideQuote && c == '#' {
			if i < l-1 && s[i+1] == '#' {
				p.c.pendingUserComment += s[i:] + "\n"
			}
			return strings.TrimSpace(s[:i])
		}
	}
	return s
}

func trimWS(s string) string {
	return strings.Trim(s, " \t\n\r\f\v")
}

func (p *cfgParser) processString(raw, name string) string {
	orig := trimWS(raw)
	s := p.stripComment(orig)
	l := len(s)
	if l >= 2 && s[0] == '"' && s[l-1] == '"' &&
		(s[l-2] != '\\' || (l >= 3 && s[l-2] == '\\' && s[l-3] == '\\')) {
		s = s[1 : l-1]
		l = len(s)
	}
	warned := false
	var result strings.Builder
	for i := 0; i < l; i++ {
		c := s[i]
		if c == '\\' {
			if i < l-1 && s[i+1] == '"' {
				result.WriteByte('"')
			} else {
				result.WriteByte(c)
				if i < l-1 {
					result.WriteByte(s[i+1])
				}
			}
			i++
		} else if c == '"' {
			if !warned {
				configWarn("Invalid value for '%s' tag at line %d, file %s: Value '%s' is not properly quoted\n", name, p.lineNr-1, p.fileName, orig)
			}
			warned = true
		} else {
			result.WriteByte(c)
		}
	}
	return result.String()
}

func (p *cfgParser) processList(raw, name string) []string {
	allowComma := name != "PREDEFINED"
	orig := trimWS(raw)
	s := p.stripComment(orig)
	l := len(s)
	var res []string
	var elem strings.Builder
	addElem := func() {
		if elem.Len() > 0 {
			e := elem.String()
			res = append(res, e)
			elem.Reset()
		}
	}
	needsSep := false
	insideQuote := false
	warned := false
	for i := 0; i < l; i++ {
		c := s[i]
		if !needsSep && c == '\\' {
			if i < l-1 && s[i+1] == '"' {
				elem.WriteByte('"')
			} else {
				elem.WriteByte(c)
				if i < l-1 {
					elem.WriteByte(s[i+1])
				}
			}
			i++
		} else if !needsSep && c == '"' {
			if !insideQuote {
				insideQuote = true
			} else {
				insideQuote = false
				needsSep = true
			}
		} else if !insideQuote && ((c == ',' && allowComma) || isSpaceByte(c)) {
			needsSep = false
			addElem()
		} else {
			if needsSep {
				if !warned {
					sep := ""
					if allowComma {
						sep = "or comma "
					}
					configWarn("Invalid value for '%s' tag at line %d, file %s: Values in list '%s' are not properly space %sseparated\n", name, p.lineNr-1, p.fileName, orig, sep)
					warned = true
				}
				needsSep = false
				i--
				addElem()
			} else {
				elem.WriteByte(c)
			}
		}
	}
	addElem()
	if insideQuote {
		configWarn("Invalid value for '%s' tag at line %d, file %s: Values in list '%s' are not properly quoted\n", name, p.lineNr-1, p.fileName, orig)
	}
	// trim elements
	out := res[:0]
	for _, e := range res {
		e = trimWS(e)
		if e != "" {
			out = append(out, e)
		}
	}
	return out
}

func (p *cfgParser) readIncludeFile(incName string) bool {
	if p.includeDepth >= 10 {
		configErr("maximum include depth (%d) reached, %s is not included. Aborting...\n", 10, incName)
		os.Exit(1)
	}
	inc := incName
	inc = strings.TrimPrefix(inc, "\"")
	inc = strings.TrimSuffix(inc, "\"")
	found := ""
	if fileExists(inc) {
		found = inc
	} else {
		for _, ip := range p.includePaths {
			cand := filepath.Join(ip, inc)
			if fileExists(cand) {
				found = cand
				break
			}
		}
	}
	if found == "" {
		configErr("@INCLUDE = %s: not found!\n", inc)
		os.Exit(1)
	}
	data, err := os.ReadFile(found)
	if err != nil {
		configErr("@INCLUDE = %s: not found!\n", inc)
		os.Exit(1)
	}
	oldName := p.fileName
	oldLine := p.lineNr
	p.fileName = inc
	p.includeDepth++
	p.parse(data)
	p.includeDepth--
	p.fileName = oldName
	p.lineNr = oldLine
	return true
}

func fileExists(name string) bool {
	st, err := os.Stat(name)
	return err == nil && !st.IsDir()
}

// parseConfigFile parses a config file ("-" means stdin).
func (c *Config) parseFile(fileName string, update bool) bool {
	var data []byte
	var err error
	if fileName == "-" {
		data, err = readAllStdin()
	} else {
		data, err = os.ReadFile(fileName)
	}
	if err != nil {
		configErr("could not open file %s for reading\n", fileName)
		return false
	}
	p := &cfgParser{c: c, update: update, lineNr: 1, fileName: fileName}
	if fileName == "-" {
		p.fileName = "<stdin>"
	}
	c.pendingUserComment = ""
	p.parse(data)
	return true
}

func readAllStdin() ([]byte, error) {
	var buf []byte
	tmp := make([]byte, 65536)
	for {
		n, err := os.Stdin.Read(tmp)
		buf = append(buf, tmp[:n]...)
		if err != nil {
			break
		}
	}
	return buf, nil
}

// ---------------------------------------------------------------------------
// Post processing

func substEnvVarsInString(s string) string {
	if s == "" {
		return s
	}
	var b strings.Builder
	i := 0
	for i < len(s) {
		if s[i] == '$' && i+1 < len(s) && s[i+1] == '(' {
			j := i + 2
			for j < len(s) && isEnvChar(s[j]) {
				j++
			}
			if j < len(s) && s[j] == ')' && j > i+2 {
				name := s[i+2 : j]
				b.WriteString(os.Getenv(name))
				i = j + 1
				continue
			}
		}
		b.WriteByte(s[i])
		i++
	}
	return trimWS(b.String())
}

func isEnvChar(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' || c == '.' || c == '-' || c == '(' && false
}

func substEnvVarsInList(l []string) []string {
	var out []string
	for _, e := range l {
		r := substEnvVarsInString(e)
		// split result on whitespace/comma unless quoted
		if r == "" {
			continue
		}
		if strings.ContainsAny(e, "$") && !strings.HasPrefix(e, "\"") {
			// split the substituted value into separate items
			parts := splitEnvList(r)
			out = append(out, parts...)
		} else {
			out = append(out, r)
		}
	}
	return out
}

func splitEnvList(s string) []string {
	var out []string
	var cur strings.Builder
	inQuote := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '"' {
			inQuote = !inQuote
			continue
		}
		if !inQuote && (c == ' ' || c == '\t' || c == ',') {
			if cur.Len() > 0 {
				out = append(out, cur.String())
				cur.Reset()
			}
			continue
		}
		cur.WriteByte(c)
	}
	if cur.Len() > 0 {
		out = append(out, cur.String())
	}
	return out
}

func (c *Config) substEnvVars() {
	for _, it := range c.items {
		switch it.Kind {
		case KindString, KindEnum, KindInt, KindBool:
			it.Str = substEnvVarsInString(it.Str)
		case KindList:
			it.List = substEnvVarsInList(it.List)
		}
	}
	for _, it := range c.extra {
		if it.OrgKind == KindList {
			it.List = substEnvVarsInList(it.List)
		} else {
			it.Str = substEnvVarsInString(it.Str)
		}
	}
}

func parseBoolStr(s string) (bool, bool) {
	v := strings.ToLower(trimWS(s))
	switch v {
	case "yes", "true", "1", "y", "t":
		return true, true
	case "no", "false", "0", "n", "f", "":
		return false, true
	}
	return false, false
}

func (c *Config) convertStrToVal(it *ConfigItem) {
	switch it.Kind {
	case KindBool:
		v := trimWS(it.Str)
		if v == "" {
			it.BoolVal, _ = parseBoolStr(it.DefStr)
			return
		}
		b, ok := parseBoolStr(v)
		if !ok {
			configWarn("argument '%s' for option %s is not a valid boolean value\nUsing the default: %s!\n", v, it.Name, it.DefStr)
			it.BoolVal, _ = parseBoolStr(it.DefStr)
			it.Str = it.DefStr
			return
		}
		it.BoolVal = b
	case KindInt:
		v := trimWS(it.Str)
		if v == "" {
			it.IntVal, _ = strconv.Atoi(it.DefStr)
			return
		}
		x, err := strconv.Atoi(v)
		if err != nil || x < it.Min || x > it.Max {
			configWarn("argument '%s' for option %s is not a valid number in the range [%d..%d]!\nUsing the default: %s!\n", v, it.Name, it.Min, it.Max, it.DefStr)
			it.IntVal, _ = strconv.Atoi(it.DefStr)
			it.Str = it.DefStr
			return
		}
		it.IntVal = x
	case KindEnum:
		v := trimWS(it.Str)
		if v == "" {
			it.Str = it.DefStr
			return
		}
		for _, e := range it.EnumVals {
			if strings.EqualFold(e, v) {
				it.Str = e
				return
			}
		}
		configWarn("argument '%s' for option %s is not a valid enum value\nUsing the default: %s!\n", v, it.Name, it.DefStr)
		it.Str = it.DefStr
	}
}

func (c *Config) convertAll() {
	for _, it := range c.items {
		c.convertStrToVal(it)
	}
}

func (c *Config) updateObsolete() {
	ts := c.get("TIMESTAMP")
	for _, n := range []string{"HTML_TIMESTAMP", "LATEX_TIMESTAMP"} {
		o := c.get(n)
		if o.Present {
			if b, ok := parseBoolStr(o.Str); ok && b && trimWS(o.Str) != "" {
				ts.Str = "YES"
			}
		}
	}
	fn := c.get("DOT_FONTNAME")
	if fn.Present && trimWS(fn.Str) != "" {
		v := trimWS(fn.Str)
		if strings.ContainsAny(v, " \t") {
			v = "\"" + v + "\""
		}
		updateAttr(c.get("DOT_COMMON_ATTR"), "fontname", v)
		updateAttr(c.get("DOT_EDGE_ATTR"), "labelfontname", v)
	}
	fs := c.get("DOT_FONTSIZE")
	if fs.Present && trimWS(fs.Str) != "" {
		v := trimWS(fs.Str)
		updateAttr(c.get("DOT_COMMON_ATTR"), "fontsize", v)
		updateAttr(c.get("DOT_EDGE_ATTR"), "labelfontsize", v)
	}
}

func updateAttr(it *ConfigItem, key, val string) {
	s := it.Str
	parts := []string{}
	if trimWS(s) != "" {
		parts = splitAttrs(s)
	}
	found := false
	for i, p := range parts {
		k := p
		if idx := strings.Index(p, "="); idx >= 0 {
			k = p[:idx]
		}
		if trimWS(k) == key {
			parts[i] = key + "=" + val
			found = true
		}
	}
	if !found {
		parts = append(parts, key+"="+val)
	}
	it.Str = strings.Join(parts, ",")
}

func splitAttrs(s string) []string {
	var out []string
	inQ := false
	start := 0
	for i := 0; i < len(s); i++ {
		if s[i] == '"' {
			inQ = !inQ
		} else if s[i] == ',' && !inQ {
			out = append(out, s[start:i])
			start = i + 1
		}
	}
	out = append(out, s[start:])
	return out
}

// postProcess performs environment substitution and value conversion
func (c *Config) postProcess(clearHeaderAndFooter bool, compare bool) {
	if !compare || !noEnvCompare {
		c.substEnvVars()
	}
	c.updateObsolete()
	if !(compare && noEnvCompare) {
		c.convertAll()
	}
	if clearHeaderAndFooter {
		cfgSetStr("HTML_HEADER", "")
		cfgSetStr("HTML_FOOTER", "")
		cfgSetStr("LATEX_HEADER", "")
		cfgSetStr("LATEX_FOOTER", "")
	}
}

var noEnvCompare bool

// ---------------------------------------------------------------------------
// Writing

func needsQuoting(s string) bool {
	return strings.ContainsAny(s, " ,\n\t\"#")
}

func writeStringValue(b *strings.Builder, s string) {
	if s == "" {
		return
	}
	b.WriteByte(' ')
	if needsQuoting(s) {
		b.WriteByte('"')
		for i := 0; i < len(s); i++ {
			if s[i] == '"' {
				b.WriteByte('\\')
			}
			b.WriteByte(s[i])
		}
		b.WriteByte('"')
	} else {
		b.WriteString(s)
	}
}

func writeName(b *strings.Builder, name string) {
	b.WriteString(name)
	for i := len(name); i < 23; i++ {
		b.WriteByte(' ')
	}
	b.WriteByte('=')
}

func writeValue(b *strings.Builder, it *ConfigItem) {
	writeName(b, it.Name)
	switch it.Kind {
	case KindList:
		first := true
		for _, e := range it.List {
			if !first {
				b.WriteString(" \\\n                        ")
			}
			first = false
			writeStringValue(b, e)
		}
		b.WriteByte('\n')
	default:
		writeStringValue(b, it.Str)
		b.WriteByte('\n')
	}
}

func (c *Config) writeTemplate(compact bool, update bool) string {
	var b strings.Builder
	b.WriteString("# Doxyfile " + versionString + "\n\n")
	if !compact {
		for _, h := range templateHeader {
			b.WriteString(h + "\n")
		}
	}
	for _, it := range c.items {
		if it.Kind == KindInfo {
			b.WriteString("\n#---------------------------------------------------------------------------\n")
			b.WriteString("# " + it.Name + "\n")
			b.WriteString("#---------------------------------------------------------------------------\n")
			continue
		}
		if !compact {
			b.WriteString("\n")
			for _, d := range it.Doc {
				b.WriteString(d + "\n")
			}
			b.WriteString("\n")
		}
		if update && it.UserComment != "" {
			if !compact {
				b.WriteString(it.UserComment)
				b.WriteString("\n")
			}
		}
		writeValue(&b, it)
	}
	if update && c.pendingUserComment != "" {
		if !compact {
			b.WriteString("\n")
			b.WriteString(c.pendingUserComment)
		}
	}
	return b.String()
}

func listEqual(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func (c *Config) compare() string {
	var b strings.Builder
	b.WriteString("# Difference with default Doxyfile " + versionString + " (" + gitHash + ")\n")
	for _, it := range c.items {
		switch it.Kind {
		case KindInfo:
			continue
		case KindString:
			if it.Name == "DOXYFILE_ENCODING" {
				continue
			}
			if trimWS(it.Str) != it.DefStr {
				writeValue(&b, it)
			}
		case KindEnum:
			if !strings.EqualFold(trimWS(it.Str), it.DefStr) {
				writeValue(&b, it)
			}
		case KindBool:
			if noEnvCompare {
				if b1, ok := parseBoolStr(it.Str); !ok || b1 != parseBoolDef(it.DefStr) {
					if trimWS(it.Str) != "" {
						writeValue(&b, it)
					}
				}
			} else if it.BoolVal != parseBoolDef(it.DefStr) {
				writeValue(&b, it)
			}
		case KindInt:
			if noEnvCompare {
				d, _ := strconv.Atoi(it.DefStr)
				x, err := strconv.Atoi(trimWS(it.Str))
				if (err != nil && trimWS(it.Str) != "") || (err == nil && x != d) {
					writeValue(&b, it)
				}
			} else {
				d, _ := strconv.Atoi(it.DefStr)
				if it.IntVal != d {
					writeValue(&b, it)
				}
			}
		case KindList:
			if !listEqual(it.List, it.DefList) {
				writeValue(&b, it)
			}
		}
	}
	return b.String()
}

func parseBoolDef(s string) bool {
	b, _ := parseBoolStr(s)
	return b
}
EOF
echo ok"}

