	{"CLANG_ASSISTED_PARSING", KindBool}, {"CLANG_ADD_INC_PATHS", KindBool},
	{"CLANG_OPTIONS", KindList}, {"CLANG_DATABASE_PATH", KindString},
}

type Config struct {
	items   []*ConfigItem
	byName  map[string]*ConfigItem
	extra   []*ConfigItem // obsolete & disabled
	pendingUserComment string
}

var cfg *Config

func newConfig() *Config {
	c := &Config{byName: map[string]*ConfigItem{}}
	for _, it := range configItems {
		n := *it
		ni := &n
		c.items = append(c.items, ni)
		if ni.Kind != KindInfo {
			c.byName[ni.Name] = ni
		}
	}
	for _, o := range obsoleteOptions {
		ni := &ConfigItem{Kind: KindObsolete, Name: o.name, OrgKind: o.kind}
