func main() {
	defer stdout.Flush()
	args := os.Args
	progName := args[0]
	optInd := 1
	genConfig := false
	shortList := false
	updateConfig := false
	quiet := false
	diffMode := 0 // 0=none,1=-x,2=-x_noenv
	cfg = newConfig()
	for optInd < len(args) && len(args[optInd]) >= 2 && args[optInd][0] == '-' &&
		(isAlpha(args[optInd][1]) || args[optInd][1] == '?' || args[optInd][1] == '-') {
