		switch a[1] {
		case 'g':
			genConfig = true
		case 'l':
			layoutName := "DoxygenLayout.xml"
			if optInd+1 < len(args) {
				layoutName = args[optInd+1]
			}
			writeDefaultLayoutFile(layoutName)
			exitProgram(0)
		case 'c':
			if optInd+1 >= len(args) {
				msgRaw("option \"-c\" is missing the file name to read\n")
				devUsage()
				exitProgram(1)
			}
			g_commentFileName = args[optInd+1]
			optInd++
			g_singleComment = true
			quiet = true
		case 'd':
			label := getArg(args, &optInd)
			if label == "" {
				devUsage()
				exitProgram(0)
			}
			if !setDebugFlag(label) {
				msgRaw(fmt.Sprintf("option \"-d\" has unknown debug specifier: \"%s\".\n", label))
				devUsage()
				exitProgram(1)
			}
		case 't':
			errMsg("support for option \"-t\" has not been compiled in (use a debug build or a release build with tracing enabled).\n")
			exitProgram(1)
		case 'T':
			errMsg("Unknown option \"-%c\"\n", a[1])
			usage(progName)
			exitProgram(1)
		case 'x':
			if a[1:] == "x_noenv" {
				diffMode = 2
			} else if a[1:] == "x" {
				diffMode = 1
			} else {
				errMsg("option should be \"-x\" or \"-x_noenv\", found: \"%s\".\n", a)
				exitProgram(1)
			}
		case 's':
			shortList = true
		case 'u':
			updateConfig = true
		case 'e':
			formatName := getArg(args, &optInd)
			if formatName == "" {
				errMsg("option \"-e\" is missing format specifier rtf.\n")
				exitProgram(1)
			}
			if strings.EqualFold(formatName, "rtf") {
				if optInd+1 >= len(args) {
					errMsg("option \"-e rtf\" is missing an extensions file name\n")
					exitProgram(1)
				}
				writePlainFile(args[optInd+1], rtfExtensionsFile())
				exitProgram(0)
			}
			errMsg("option \"-e\" has invalid format specifier.\n")
			exitProgram(1)
		case 'f':
			listName := getArg(args, &optInd)
			if listName == "" {
				errMsg("option \"-f\" is missing list specifier.\n")
				exitProgram(1)
			}
			if strings.EqualFold(listName, "emoji") {
				if optInd+1 >= len(args) {
					errMsg("option \"-f emoji\" is missing an output file name\n")
					exitProgram(1)
				}
				writePlainFile(args[optInd+1], emojiListFile())
				exitProgram(0)
			}
			errMsg("option \"-f\" has invalid list specifier.\n")
			exitProgram(1)
		case 'w':
			formatName := getArg(args, &optInd)
			if formatName == "" {
				errMsg("option \"-w\" is missing format specifier rtf, html or latex\n")
				exitProgram(1)
			}
			if strings.EqualFold(formatName, "rtf") {
				if optInd+1 >= len(args) {
					errMsg("option \"-w rtf\" is missing a style sheet file name\n")
					exitProgram(1)
				}
				writeOutputFile(args[optInd+1], rtfStyleSheetFile())
				exitProgram(0)
			} else if strings.EqualFold(formatName, "html") || strings.EqualFold(formatName, "latex") {
				isHtml := strings.EqualFold(formatName, "html")
				if optInd+4 < len(args) || fileExists("Doxyfile") || fileExists("doxyfile") {
					df := ""
					if optInd+4 < len(args) {
						df = args[optInd+4]
					} else if fileExists("Doxyfile") {
						df = "Doxyfile"
					} else {
						df = "doxyfile"
					}
					if !cfg.parseFile(df, false) {
