			if rest == "help" {
				usage(progName)
				exitProgram(0)
			} else if rest == "version" {
				version(false)
				exitProgram(0)
			} else if rest == "Version" || rest == "VERSION" {
				version(true)
				exitProgram(0)
			} else {
				errMsg("Unknown option \"-%s\"\n", a[1:])
				usage(progName)
				exitProgram(1)
			}
		case 'b':
			unbufferedStdout = true
		case 'q':
			quiet = true
		case 'h', '?':
			usage(progName)
			exitProgram(0)
		default:
			errMsg("Unknown option \"-%c\"\n", a[1])
			usage(progName)
			exitProgram(1)
		}
