			}
			if strings.EqualFold(formatName, "rtf") {
				if optInd+1 >= len(args) {
					errMsg("option \"-w rtf\" is missing a style sheet file name\n")
					exitProgram(1)
				}
				writeOutputFile(args[optInd+1], rtfStyleSheetFile())
				exitProgram(0)
			} else if strings.EqualFold(formatName, "html") || strings.EqualFold(formatName, "latex") {
				isHtml := strings.EqualFold(formatName, "html")
				if optInd+4 < len(args) || fileExists("Doxyfile") || fileExists("doxyfile") {
					df := ""
					if optInd+4 < len(args) {
						df = args[optInd+4]
					} else if fileExists("Doxyfile") {
						df = "Doxyfile"
					} else {
						df = "doxyfile"
					}
					if !cfg.parseFile(df, false) {
						errMsg("error opening or reading configuration file %s!\n", df)
						exitProgram(1)
					}
				}
				if optInd+3 >= len(args) {
					if isHtml {
						errMsg("option \"-w html\" does not have enough arguments\n")
					} else {
						errMsg("option \"-w latex\" does not have enough arguments\n")
					}
					exitProgram(1)
				}
				cfg.postProcess(true, false)
				checkAndCorrect(cfgBool("QUIET"), false)
				if isHtml {
					writeOutputFile(args[optInd+1], htmlHeaderTemplate(args[optInd+3]))
					writeOutputFile(args[optInd+2], htmlFooterTemplate())
					writeOutputFile(args[optInd+3], htmlStyleSheet())
				} else {
					writeOutputFile(args[optInd+1], latexHeaderTemplate())
					writeOutputFile(args[optInd+2], latexFooterTemplate())
					writeOutputFile(args[optInd+3], latexStyleSheet())
				}
				exitProgram(0)
			} else {
				errMsg("Illegal format specifier \"%s\": should be one of rtf, html or latex\n", formatName)
				exitProgram(1)
			}
		case 'm':
			g_dumpSymbolMap = true
		case 'v':
			version(false)
			exitProgram(0)
		case 'V':
			version(true)
			exitProgram(0)
		case '-':
			rest := a[2:]
			if rest == "help" {
				usage(progName)
				exitProgram(0)
			} else if rest == "version" {
				version(false)
				exitProgram(0)
			} else if rest == "Version" || rest == "VERSION" {
				version(true)
				exitProgram(0)
			} else {
				errMsg("Unknown option \"-%s\"\n", a[1:])
				usage(progName)
				exitProgram(1)
			}
		case 'b':
			unbufferedStdout = true
		case 'q':
			quiet = true
		case 'h', '?':
			usage(progName)
			exitProgram(0)
		default:
			errMsg("Unknown option \"-%c\"\n", a[1])
			usage(progName)
			exitProgram(1)
		}
		optInd++
	}

	configName := ""
	if optInd >= len(args) {
		if fileExists("Doxyfile") {
			configName = "Doxyfile"
		} else if fileExists("doxyfile") {
			configName = "doxyfile"
		} else if genConfig {
			configName = "Doxyfile"
		} else {
			errMsg("Doxyfile not found and no input file specified!\n")
			usage(progName)
			exitProgram(1)
		}
	} else {
		a := args[optInd]
		if pathExists(a) || a == "-" || genConfig {
			configName = a
		} else {
			errMsg("configuration file %s not found!\n", a)
			usage(progName)
			exitProgram(1)
		}
	}

	if genConfig {
		generateConfigFile(configName, shortList, false)
		exitProgram(0)
	}

	if !cfg.parseFile(configName, updateConfig) {
		errMsg("could not open or read configuration file %s!\n", configName)
		exitProgram(1)
	}

	if diffMode != 0 {
		noEnvCompare = diffMode == 2
		cfg.postProcess(false, true)
		msgRaw(cfg.compare())
		exitProgram(0)
	}

	if updateConfig {
		cfg.updateObsolete()
		generateConfigFile(configName, shortList, true)
		exitProgram(0)
	}
	g_configFileName = configName
	if quiet {
		cfgSetBool("QUIET", true)
		cfg.get("QUIET").Str = "YES"
	}
	runDoxygen(quiet)
	exitProgram(0)
}

func pathExists(p string) bool {
	_, err := os.Stat(p)
	return err == nil
}

func generateConfigFile(configName string, shortList bool, update bool) {
	content := cfg.writeTemplate(shortList, update)
	writeToStdout := configName == "-"
	if writeToStdout {
		msgRaw(content)
		return
	}
	if st, err := os.Stat(configName); err == nil && !st.IsDir() {
		os.Remove(configName + ".bak")
		os.Rename(configName, configName+".bak")
	}
	f, err := os.Create(configName)
	if err != nil {
		errMsg("Cannot open file %s for writing\n", configName)
		exitProgram(1)
	}
	f.WriteString(content)
	f.Close()
	if !update {
		msgRaw(fmt.Sprintf("\n\nConfiguration file '%s' created.\n\n", configName))
		msgRaw("Now edit the configuration file and enter\n\n")
		if configName != "Doxyfile" && configName != "doxyfile" {
			msgRaw(fmt.Sprintf("  doxygen %s\n\n", configName))
		} else {
			msgRaw("  doxygen\n\n")
		}
		msgRaw("to generate the documentation for your project\n\n")
	} else {
		msgRaw(fmt.Sprintf("\n\nConfiguration file '%s' updated.\n\n", configName))
	}
}
