func hsl2rgb(h, s, l float64) (float64, float64, float64) {
	r, g, b := l, l, l
	var v float64
	if l <= 0.5 {
		v = l * (1.0 + s)
	} else {
		v = l + s - l*s
	}
	if v > 0 {
		m := l + l - v
		sv := (v - m) / v
		h *= 6.0
		sextant := int(h)
		fract := h - float64(sextant)
		vsf := v * sv * fract
		mid1 := m + vsf
		mid2 := v - vsf
		switch sextant {
		case 0:
			r, g, b = v, mid1, m
		case 1:
			r, g, b = mid2, v, m
		case 2:
			r, g, b = m, v, mid1
		case 3:
			r, g, b = m, mid2, v
		case 4:
			r, g, b = mid1, m, v
		case 5:
			r, g, b = v, m, mid2
		}
	}
	return r, g, b
}

func hexVal(c byte) int {
	switch {
	case c >= '0' && c <= '9':
		return int(c - '0')
	case c >= 'a' && c <= 'f':
		return int(c-'a') + 10
	case c >= 'A' && c <= 'F':
		return int(c-'A') + 10
	}
	return 0
}

