func replaceColorMarkers(s string) string {
	hue := cfgInt("HTML_COLORSTYLE_HUE")
	sat := cfgInt("HTML_COLORSTYLE_SAT")
	gamma := cfgInt("HTML_COLORSTYLE_GAMMA")
	const hex = "0123456789ABCDEF"
	return colorMarkerRe.ReplaceAllStringFunc(s, func(m string) string {
