#!/usr/bin/env python3
"""Differential tester: runs a shell snippet with $EXE=original and $EXE=ours in fresh dirs, compares."""
import subprocess, sys, os, shutil, tempfile, filecmp
ORIG='/workspace/executable'
OURS='/workspace/build/doxy'
def run(exe, setup, cmd, d):
    os.makedirs(d, exist_ok=True)
    if setup:
        subprocess.run(setup, shell=True, cwd=d)
    env=dict(os.environ); env['EXE']=exe
    p=subprocess.run(cmd, shell=True, cwd=d, env=env, capture_output=True, timeout=120)
    return p
def tree(d):
    res={}
    for root,dirs,files in os.walk(d):
        for f in files:
            full=os.path.join(root,f)
            res[os.path.relpath(full,d)]=open(full,'rb').read()
    return res
def compare(setup, cmd, show=True, files=True):
    base=tempfile.mkdtemp(prefix='cmp')
    a=os.path.join(base,'w'); b=os.path.join(base,'w2')
    pa=run(ORIG,setup,cmd,a)
    shutil.move(a, os.path.join(base,'orig'))
    pb=run(OURS,setup,cmd,a)
    shutil.move(a, os.path.join(base,'ours'))
    a=os.path.join(base,'orig'); b=os.path.join(base,'ours')
    ok=True
    msgs=[]
    def norm(x): return x.replace(ORIG.encode(),b'EXE').replace(OURS.encode(),b'EXE')
    if norm(pa.stdout)!=norm(pb.stdout): ok=False; msgs.append('stdout differs')
    if norm(pa.stderr)!=norm(pb.stderr): ok=False; msgs.append('stderr differs')
    if pa.returncode!=pb.returncode: ok=False; msgs.append('rc %d vs %d'%(pa.returncode,pb.returncode))
    if files:
        ta=tree(a); tb=tree(b)
        for k in sorted(set(ta)|set(tb)):
            if k not in ta: ok=False; msgs.append('extra file '+k)
            elif k not in tb: ok=False; msgs.append('missing file '+k)
            elif ta[k]!=tb[k]: ok=False; msgs.append('file differs '+k)
    if show:
        print(('OK   ' if ok else 'FAIL ')+cmd+('' if ok else '\n     '+'\n     '.join(msgs[:20])+'\n     dir='+base))
    if ok: shutil.rmtree(base)
    return ok
if __name__=='__main__':
    setup=None
    args=sys.argv[1:]
    if args and args[0]=='-s':
        setup=args[1]; args=args[2:]
    for c in args:
        compare(setup,c)
