package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

var warnLogFile *os.File
var warningCount int
var quietMode bool

// progress message
func msg(format string, args ...interface{}) {
	if quietMode {
		return
	}
	s := format
	if len(args) > 0 {
		s = fmt.Sprintf(format, args...)
	}
	msgRaw(s)
}

func warnOut(s string) {
	stdout.Flush()
	if warnLogFile != nil {
		warnLogFile.WriteString(s)
	} else {
		os.Stderr.WriteString(s)
	}
}

func formatWarning(file string, line int, prefix, text string) string {
	if file == "" {
		return prefix + text
	}
	fmtStr := cfgStr("WARN_FORMAT")
	lineStr := ""
	if line > 0 {
		lineStr = strconv.Itoa(line)
	}
	r := strings.NewReplacer("$file", file, "$line", lineStr, "$text", prefix+text, "$version", versionString)
	return r.Replace(fmtStr)
}

// warn emits a warning with location info
func warnAt(file string, line int, format string, args ...interface{}) {
	if !cfgBool("WARNINGS") {
		return
	}
	text := fmt.Sprintf(format, args...)
	warningCount++
	s := formatWarning(file, line, "warning: ", text)
	if !strings.HasSuffix(s, "\n") {
		s += "\n"
	}
	warnOut(s)
}

func warnUndocAt(file string, line int, format string, args ...interface{}) {
	if !cfgBool("WARN_IF_UNDOCUMENTED") {
		return
	}
	warnAt(file, line, format, args...)
}

func warnDocAt(file string, line int, format string, args ...interface{}) {
	if !cfgBool("WARN_IF_DOC_ERROR") {
		return
	}
	warnAt(file, line, format, args...)
}

func warnIncompleteAt(file string, line int, format string, args ...interface{}) {
	if !cfgBool("WARN_IF_INCOMPLETE_DOC") {
		return
	}
	warnAt(file, line, format, args...)
}

// warnPlain prints "warning: ..." without location
func warnPlain(format string, args ...interface{}) {
	text := fmt.Sprintf(format, args...)
	warningCount++
	warnOut("warning: " + text)
}

func errPlain(format string, args ...interface{}) {
	text := fmt.Sprintf(format, args...)
	warnOut("error: " + text)
}
EOF
echo ok"}

