package main

import (
	"strings"
)

type TokKind int

const (
	tkEOF TokKind = iota
	tkIdent
	tkNumber
	tkString
	tkChar
	tkPunct
	tkComment
	tkPP
)

type Token struct {
	Kind    TokKind
	Text    string
	Line    int
	Col     int
	EndLine int
	// comment info
	Special  bool   // doc comment
	After    bool   // ///< style
	CppStyle bool   // /// or //!
	Bang     bool   // //! or /*!
	Lines    int    // number of lines for cpp-style blocks
	Body     string // comment content with markers stripped
	// preprocessor
	PPName  string
	PPArgs  string
	PPHasArgs bool
	PPBody  string
	PPKind  string
	SpaceBefore bool
	NewlineBefore bool
}

type lexer struct {
	src   string
	pos   int
	line  int
	col   int
	toks  []Token
	file  string
	pp    *preproc
	atLineStart bool
	skipping bool
	spaceBefore bool
	newlineBefore bool
}

func isIdStart(c byte) bool {
	return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c >= 0x80 || c == '$'
}
func isIdChar(c byte) bool { return isIdStart(c) || (c >= '0' && c <= '9') }
func isDigit(c byte) bool  { return c >= '0' && c <= '9' }

func (lx *lexer) peek(o int) byte {
	if lx.pos+o < len(lx.src) {
		return lx.src[lx.pos+o]
	}
	return 0
}

func (lx *lexer) adv() byte {
	c := lx.src[lx.pos]
	lx.pos++
	if c == '\n' {
		lx.line++
		lx.col = 1
	} else if c == '\t' {
		ts := tabSize()
		lx.col += ts - ((lx.col - 1) % ts)
	} else {
		lx.col++
	}
	return c
}

func tabSize() int {
	if cfg == nil {
		return 4
	}
	t := cfgInt("TAB_SIZE")
	if t <= 0 {
		return 4
	}
	return t
}

func (lx *lexer) emit(t Token) {
	t.SpaceBefore = lx.spaceBefore
	t.NewlineBefore = lx.newlineBefore
	lx.spaceBefore = false
	lx.newlineBefore = false
	if lx.skipping && t.Kind != tkPP {
		return
	}
	lx.toks = append(lx.toks, t)
}

// tokenize C-like source. Preprocessor directives are processed via pp.
func tokenizeC(src string, file string, pp *preproc) []Token {
	lx := &lexer{src: src, line: 1, col: 1, file: file, pp: pp, atLineStart: true}
	lx.run()
	lx.toks = append(lx.toks, Token{Kind: tkEOF, Line: lx.line, Col: lx.col})
	return lx.toks
}

func (lx *lexer) run() {
	for lx.pos < len(lx.src) {
		c := lx.peek(0)
		if c == '\n' {
			lx.adv()
			lx.atLineStart = true
			lx.newlineBefore = true
			lx.spaceBefore = true
			continue
		}
		if c == ' ' || c == '\t' || c == '\r' || c == '\f' || c == '\v' {
			lx.adv()
			lx.spaceBefore = true
			continue
		}
		if c == '\\' && (lx.peek(1) == '\n' || (lx.peek(1) == '\r' && lx.peek(2) == '\n')) {
			lx.adv()
			for lx.peek(0) != '\n' {
				lx.adv()
			}
			lx.adv()
			continue
		}
		if c == '#' && lx.atLineStart {
			lx.directive()
			continue
		}
		lx.atLineStart = false
		if c == '/' && lx.peek(1) == '*' {
			lx.cComment()
			continue
		}
		if c == '/' && lx.peek(1) == '/' {
			lx.cppComment()
			continue
		}
		line, col := lx.line, lx.col
		if isIdStart(c) {
			start := lx.pos
			for lx.pos < len(lx.src) && isIdChar(lx.peek(0)) {
				lx.adv()
			}
			word := lx.src[start:lx.pos]
			// raw string / prefixed string literals
			if (word == "R" || word == "u8R" || word == "uR" || word == "UR" || word == "LR") && lx.peek(0) == '"' {
				lx.rawString(line, col, word)
				continue
			}
			if (word == "u8" || word == "u" || word == "U" || word == "L") && (lx.peek(0) == '"' || lx.peek(0) == '\'') {
				q := lx.peek(0)
				s := lx.quoted(q)
				k := tkString
				if q == '\'' {
					k = tkChar
				}
				lx.emit(Token{Kind: k, Text: word + s, Line: line, Col: col, EndLine: lx.line})
				continue
			}
			lx.emit(Token{Kind: tkIdent, Text: word, Line: line, Col: col, EndLine: lx.line})
			continue
		}
		if isDigit(c) || (c == '.' && isDigit(lx.peek(1))) {
			start := lx.pos
			for lx.pos < len(lx.src) {
				d := lx.peek(0)
				if isIdChar(d) || d == '.' || d == '\'' {
					lx.adv()
				} else if (d == '+' || d == '-') && lx.pos > start && strings.ContainsRune("eEpP", rune(lx.src[lx.pos-1])) {
					lx.adv()
				} else {
					break
				}
			}
			lx.emit(Token{Kind: tkNumber, Text: lx.src[start:lx.pos], Line: line, Col: col, EndLine: lx.line})
			continue
		}
		if c == '"' || c == '\'' {
			s := lx.quoted(c)
			k := tkString
			if c == '\'' {
				k = tkChar
			}
			lx.emit(Token{Kind: k, Text: s, Line: line, Col: col, EndLine: lx.line})
			continue
		}
		// punctuation
		p := string(c)
		two := ""
		if lx.pos+1 < len(lx.src) {
			two = lx.src[lx.pos : lx.pos+2]
		}
		three := ""
		if lx.pos+2 < len(lx.src) {
			three = lx.src[lx.pos : lx.pos+3]
		}
		switch {
		case three == "..." || three == "<=>" || three == "->*" || three == "<<=" :
			p = three
		case two == "::" || two == "->" || two == "++" || two == "--" || two == "&&" || two == "||" ||
			two == "==" || two == "!=" || two == "<=" || two == "+=" || two == "-=" ||
			two == "*=" || two == "/=" || two == "%=" || two == "&=" || two == "|=" || two == "^=" || two == "<<" || two == ".*":
			p = two
		}
		for i := 0; i < len(p); i++ {
			lx.adv()
		}
		lx.emit(Token{Kind: tkPunct, Text: p, Line: line, Col: col, EndLine: lx.line})
	}
}

func (lx *lexer) quoted(q byte) string {
	start := lx.pos
	lx.adv()
	for lx.pos < len(lx.src) {
		d := lx.peek(0)
		if d == '\\' && lx.pos+1 < len(lx.src) {
			lx.adv()
			lx.adv()
			continue
		}
		if d == '\n' {
			break
		}
		lx.adv()
		if d == q {
			break
		}
	}
	return lx.src[start:lx.pos]
}

func (lx *lexer) rawString(line, col int, prefix string) {
	start := lx.pos
	lx.adv() // "
	dstart := lx.pos
	for lx.pos < len(lx.src) && lx.peek(0) != '(' && lx.peek(0) != '\n' {
		lx.adv()
	}
	delim := lx.src[dstart:lx.pos]
	end := ")" + delim + "\""
	idx := strings.Index(lx.src[lx.pos:], end)
	if idx < 0 {
		idx = len(lx.src) - lx.pos - len(end)
		if idx < 0 {
			idx = 0
		}
	}
	target := lx.pos + idx + len(end)
	if target > len(lx.src) {
		target = len(lx.src)
	}
	for lx.pos < target {
		lx.adv()
	}
	lx.emit(Token{Kind: tkString, Text: prefix + lx.src[start:lx.pos], Line: line, Col: col, EndLine: lx.line})
}

func (lx *lexer) cComment() {
	line, col := lx.line, lx.col
	start := lx.pos
	lx.adv()
	lx.adv()
	for lx.pos < len(lx.src) && !(lx.peek(0) == '*' && lx.peek(1) == '/') {
		lx.adv()
	}
	if lx.pos < len(lx.src) {
		lx.adv()
		lx.adv()
	}
	raw := lx.src[start:lx.pos]
	t := Token{Kind: tkComment, Text: raw, Line: line, Col: col, EndLine: lx.line}
	inner := raw[2:]
	if strings.HasSuffix(inner, "*/") {
		inner = inner[:len(inner)-2]
	}
	if (strings.HasPrefix(inner, "*") && !strings.HasPrefix(inner, "**") && inner != "*" && !strings.HasPrefix(inner, "*/")) || strings.HasPrefix(inner, "!") {
		t.Special = true
		t.Bang = inner[0] == '!'
		inner = inner[1:]
		if strings.HasPrefix(inner, "<") {
			t.After = true
			inner = inner[1:]
		}
		t.Body = stripCCommentBody(inner)
	} else if strings.HasPrefix(inner, "**") && len(inner) > 2 && inner[2] != '*' && inner[2] != '/' {
		// "/***" is not special
	}
	lx.emit(t)
}

// stripCCommentBody removes leading '*' decoration from each line of a C comment body
func stripCCommentBody(s string) string {
	lines := strings.Split(s, "\n")
	for i := 1; i < len(lines); i++ {
		l := lines[i]
		j := 0
		for j < len(l) && (l[j] == ' ' || l[j] == '\t') {
			j++
		}
		if j < len(l) && l[j] == '*' && !(j+1 < len(l) && l[j+1] == '/') {
			// replace leading spaces + '*' by spaces to keep indentation
			lines[i] = strings.Repeat(" ", j+1) + l[j+1:]
		}
	}
	return strings.Join(lines, "\n")
}

func (lx *lexer) cppComment() {
	line, col := lx.line, lx.col
	start := lx.pos
	for lx.pos < len(lx.src) && lx.peek(0) != '\n' {
		if lx.peek(0) == '\\' && lx.peek(1) == '\n' {
			lx.adv()
		}
		lx.adv()
	}
	raw := lx.src[start:lx.pos]
	t := Token{Kind: tkComment, Text: raw, Line: line, Col: col, EndLine: lx.line, CppStyle: true, Lines: 1}
	if (strings.HasPrefix(raw, "///") && !strings.HasPrefix(raw, "////")) || strings.HasPrefix(raw, "//!") {
		t.Special = true
		t.Bang = raw[2] == '!'
		body := raw[3:]
		if strings.HasPrefix(body, "<") {
			t.After = true
			body = body[1:]
		}
		t.Body = body
		// merge with previous special cpp comment on the immediately preceding line
		if n := len(lx.toks); n > 0 && !lx.skipping {
			prev := &lx.toks[n-1]
			if prev.Kind == tkComment && prev.Special && prev.CppStyle && prev.EndLine == line-1 && prev.Bang == t.Bang && !t.After && lx.onlyWhitespaceBeforeOnLine(start) {
				prev.Body += "\n" + body
				prev.EndLine = line
				prev.Text += "\n" + raw
				prev.Lines++
				return
			}
		}
	}
	lx.emit(t)
}

func (lx *lexer) onlyWhitespaceBeforeOnLine(pos int) bool {
	i := pos - 1
	for i >= 0 && lx.src[i] != '\n' {
		if lx.src[i] != ' ' && lx.src[i] != '\t' {
			return false
		}
		i--
	}
	return true
}

func (lx *lexer) directive() {
	line := lx.line
	start := lx.pos
	// read the full directive (with continuations), removing comments
	var b strings.Builder
	lx.adv() // '#'
	for lx.pos < len(lx.src) {
		c := lx.peek(0)
		if c == '\\' && lx.peek(1) == '\n' {
			lx.adv()
			lx.adv()
			b.WriteByte(' ')
			continue
		}
		if c == '\\' && lx.peek(1) == '\r' && lx.peek(2) == '\n' {
			lx.adv()
			lx.adv()
			lx.adv()
			b.WriteByte(' ')
			continue
		}
		if c == '\n' {
			break
		}
		if c == '/' && lx.peek(1) == '*' {
			// comment inside directive
			cs := lx.pos
			cl, cc := lx.line, lx.col
			lx.adv()
			lx.adv()
			for lx.pos < len(lx.src) && !(lx.peek(0) == '*' && lx.peek(1) == '/') {
				lx.adv()
			}
			if lx.pos < len(lx.src) {
				lx.adv()
				lx.adv()
			}
			raw := lx.src[cs:lx.pos]
			if strings.HasPrefix(raw, "/**<") || strings.HasPrefix(raw, "/*!<") {
				lx.pendingAfter = append(lx.pendingAfter, Token{Kind: tkComment, Text: raw, Line: cl, Col: cc, EndLine: lx.line, Special: true, After: true, Body: stripCCommentBody(strings.TrimSuffix(raw[4:], "*/"))})
			}
			b.WriteByte(' ')
			continue
		}
		if c == '/' && lx.peek(1) == '/' {
			cs := lx.pos
			cl, cc := lx.line, lx.col
			for lx.pos < len(lx.src) && lx.peek(0) != '\n' {
				lx.adv()
			}
			raw := lx.src[cs:lx.pos]
			if strings.HasPrefix(raw, "///<") || strings.HasPrefix(raw, "//!<") {
				lx.pendingAfter = append(lx.pendingAfter, Token{Kind: tkComment, Text: raw, Line: cl, Col: cc, EndLine: lx.line, Special: true, After: true, CppStyle: true, Body: raw[4:]})
			}
			break
		}
		b.WriteByte(lx.adv())
	}
	_ = start
	text := strings.TrimSpace(b.String())
	lx.handleDirective(text, line)
	for _, t := range lx.pendingAfter {
		lx.emit(t)
	}
	lx.pendingAfter = nil
	lx.atLineStart = true
}
